Transition = Tuple[np.ndarray, int, float, np.ndarray, float]


# 1) Board helpers -------------------------------------------------------------


def _get_cfg_value(cfg, attr: str, default: int) -> int:
    """Safely fetch configuration attributes (works for objects or dicts)."""
    if hasattr(cfg, attr):
        value = getattr(cfg, attr)
    elif isinstance(cfg, dict):
        value = cfg.get(attr, default)
    else:
        value = default
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _extract_board(observation) -> List[int]:
    """Return the flattened board list from observation."""
    if isinstance(observation, dict):
        board = observation.get("board")
        if board is None:
            nested = observation.get("observation")
            if isinstance(nested, dict):
                board = nested.get("board")
        return board if board is not None else []
    return getattr(observation, "board", [])


def to_grid(board_flat: List[int], cfg) -> np.ndarray:
    """Convert a flattened board into a (rows, columns) grid."""
    rows = _get_cfg_value(cfg, "rows", 6)
    cols = _get_cfg_value(cfg, "columns", 7)
    arr = np.asarray(board_flat, dtype=np.int8)
    if arr.size != rows * cols:
        arr = np.resize(arr, rows * cols)
    return arr.reshape(rows, cols)


def find_playable_columns(board_flat: List[int], cfg) -> List[int]:
    """Return the indices of columns that can accept a token."""
    if not board_flat:
        return []
    cols = _get_cfg_value(cfg, "columns", 7)
    playable: List[int] = []
    for c in range(cols):
        try:
            if board_flat[c] == 0:
                playable.append(c)
        except IndexError:
            break
    return playable


def state_from_board(board_flat: List[int], cfg) -> np.ndarray:
    """Return a (1, rows, columns) float32 state tensor."""
    rows = _get_cfg_value(cfg, "rows", 6)
    cols = _get_cfg_value(cfg, "columns", 7)
    if not board_flat:
        board_flat = [0] * (rows * cols)
    grid = to_grid(board_flat, cfg).astype(np.float32)
    return grid[np.newaxis, ...]


def playable_columns_from_state(state: np.ndarray) -> List[int]:
    grid = state[0]
    return [c for c in range(grid.shape[1]) if grid[0, c] == 0]


def state_to_tensor(state: np.ndarray) -> torch.Tensor:
    """Convert numpy state to torch tensor with batch dimension."""
    if not HAS_TORCH:
        raise ImportError("PyTorch가 없는 환경에서는 state_to_tensor를 사용할 수 없습니다.")
    return torch.from_numpy(state).float().unsqueeze(0)


def mask_invalid_columns(q_values: torch.Tensor, playable: List[int]) -> torch.Tensor:
    masked = torch.full_like(q_values, -float("inf"))
    for col in playable:
        masked[col] = q_values[col]
    return masked


def fallback_move(playable: List[int], cfg) -> int:
    """Fallback heuristic when no embedded DQN weights are provided."""
    if not playable:
        return 0
    center = _get_cfg_value(cfg, "columns", 7) // 2
    if center in playable:
        return center
    return random.choice(playable)


# 2) Replay Buffer -------------------------------------------------------------


class ReplayBuffer:
    """Simple FIFO buffer for DQN transitions."""

    def __init__(self, capacity: int = 50_000):
        self.capacity = capacity
        self.memory: Deque[Transition] = collections.deque(maxlen=capacity)

    def __len__(self) -> int:
        return len(self.memory)

    def push(
        self,
        state: np.ndarray,
        action: int,
        reward: float,
        next_state: np.ndarray,
        done_mask: float,
    ) -> None:
        self.memory.append(
            (
                np.array(state, copy=True),
                int(action),
                float(reward),
                np.array(next_state, copy=True),
                float(done_mask),
            )
        )

    def sample(
        self, batch_size: int
    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
        batch = random.sample(self.memory, batch_size)
        states, actions, rewards, next_states, masks = zip(*batch)

        return (
            np.stack(states).astype(np.float32),
            np.asarray(actions, dtype=np.int64),
            np.asarray(rewards, dtype=np.float32),
            np.stack(next_states).astype(np.float32),
            np.asarray(masks, dtype=np.float32),
        )


# 3) Q-Network -----------------------------------------------------------------


if HAS_TORCH:

    class QNetwork(nn.Module):
        """Simple convolutional Q-network tailored to the 6x7 ConnectX board."""

        def __init__(self, action_dim: int = 7):
            super().__init__()
            self.cnn = nn.Sequential(
                nn.Conv2d(1, 32, kernel_size=3, stride=1),
                nn.ReLU(),
                nn.Conv2d(32, 64, kernel_size=3, stride=1),
                nn.ReLU(),
                nn.Flatten(),
            )
            self.fc = nn.Linear(64 * 2 * 3, action_dim)

        def forward(self, x: torch.Tensor) -> torch.Tensor:
            return self.fc(self.cnn(x))

        def act(self, state_tensor: torch.Tensor, playable: List[int], epsilon: float = 0.0) -> int:
            if not playable:
                return 0
            if epsilon > 0.0 and random.random() < epsilon:
                return random.choice(playable)

            q_values = self.forward(state_tensor)[0]
            masked = mask_invalid_columns(q_values, playable)
            return int(masked.argmax().item())

else:

    class QNetwork:  # pragma: no cover - placeholder when torch is unavailable
        def __init__(self, *_args, **_kwargs):
            raise ImportError("PyTorch is required to instantiate QNetwork.")


# 4) Training environment & helpers -------------------------------------------


class ConnectFourTrainer:
    """Lightweight wrapper for Kaggle's environment used during training."""

    def __init__(self, enemy: str = "random"):
        from kaggle_environments import make

        base_env = make("connectx", debug=True)
        self._trainer = base_env.train([None, enemy])
        self.config = base_env.configuration
        self.rows = self.config.rows
        self.cols = self.config.columns
        self._cells = self.rows * self.cols
        self._mid_height = max(1, (self.rows + 1) // 2)
        self._last_obs = None

    def reset(self) -> np.ndarray:
        self._last_obs = self._trainer.reset()
        return self._to_state(self._last_obs["board"])

    def step(self, action: int) -> Tuple[np.ndarray, float, bool]:
        action = int(action)
        board_flat = self._last_obs["board"]
        heights_before = self._column_heights(board_flat)

        if board_flat[action] != 0:
            return self._to_state(board_flat), -10.0, True

        self._last_obs, env_reward, done, _ = self._trainer.step(action)
        shaped_reward = self._reward(env_reward, done)
        shaped_reward += self._placement_shaping(action, heights_before, board_flat)
        return self._to_state(self._last_obs["board"]), shaped_reward, done

    def _to_state(self, board_flat: List[int]) -> np.ndarray:
        return np.asarray(board_flat, dtype=np.float32).reshape(1, self.rows, self.cols)

    def _column_heights(self, board_flat: List[int]) -> List[int]:
        grid = np.asarray(board_flat, dtype=np.int8).reshape(self.rows, self.cols)
        return np.count_nonzero(grid, axis=0).tolist()

    def _reward(self, env_reward: float, done: bool) -> float:
        if env_reward == 1:
            return 1.0
        if done:
            return -1.0
        return 1.0 / self._cells

    def _placement_shaping(self, action: int, heights_before: List[int], board_flat: List[int]) -> float:
        if action < 0 or action >= len(heights_before):
            return 0.0

        reward = 0.0
        threshold = self._mid_height
        height = heights_before[action]
        all_columns_tall = all(h >= threshold for h in heights_before)

        if not all_columns_tall:
            if height < threshold:
                bonus = 0.05
                if height == 0:
                    bonus += 0.05
                reward += bonus
            else:
                reward -= 0.03
        else:
            if height >= threshold:
                reward += 0.04 + 0.01 * min(height, self.rows) / self.rows
            else:
                reward -= 0.02

        reward += self._blocking_bonus(action, board_flat, heights_before)
        return reward

    def _blocking_bonus(self, action: int, board_flat: List[int], heights_before: List[int]) -> float:
        row = self._row_from_heights(heights_before, action)
        if row is None:
            return 0.0

        idx = row * self.cols + action
        if idx < 0 or idx >= len(board_flat):
            return 0.0
        if board_flat[idx] != 0:
            return 0.0

        grid = np.asarray(board_flat, dtype=np.int8).reshape(self.rows, self.cols).copy()
        grid[row, action] = 2
        max_align = self._max_alignment(grid, row, action, 2)

        if max_align >= self.config.inarow:
            return 0.15
        threat_threshold = max(2, self.config.inarow - 1)
        if max_align >= threat_threshold:
            return 0.08
        return 0.0

    def _row_from_heights(self, heights: List[int], column: int) -> Optional[int]:
        if column < 0 or column >= len(heights):
            return None
        height = heights[column]
        row = self.rows - height - 1
        if row < 0:
            return None
        return row

    def _max_alignment(self, grid: np.ndarray, row: int, col: int, player: int) -> int:
        best = 1
        directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
        for dr, dc in directions:
            total = 1
            total += self._count_direction(grid, row, col, dr, dc, player)
            total += self._count_direction(grid, row, col, -dr, -dc, player)
            best = max(best, total)
        return best

    def _count_direction(self, grid: np.ndarray, row: int, col: int, dr: int, dc: int, player: int) -> int:
        r, c = row + dr, col + dc
        cnt = 0
        while 0 <= r < self.rows and 0 <= c < self.cols and grid[r, c] == player:
            cnt += 1
            r += dr
            c += dc
        return cnt


def epsilon_by_episode(episode: int) -> float:
    progress = min(1.0, episode / EPSILON_DECAY_EPISODES)
    return EPSILON_START - (EPSILON_START - EPSILON_END) * progress


def optimize_td(
    q_net: QNetwork,
    target_net: QNetwork,
    batch: Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, np.ndarray],
    optimizer: torch.optim.Optimizer,
    gamma: float,
) -> float:
    if not HAS_TORCH:
        raise ImportError("PyTorch is required to optimize the DQN.")
    states, actions, rewards, next_states, masks = batch

    states_t = torch.from_numpy(states).to(DEVICE)
    actions_t = torch.from_numpy(actions).long().unsqueeze(-1).to(DEVICE)
    rewards_t = torch.from_numpy(rewards).unsqueeze(-1).to(DEVICE)
    next_states_t = torch.from_numpy(next_states).to(DEVICE)
    masks_t = torch.from_numpy(masks).unsqueeze(-1).to(DEVICE)

    q_values = q_net(states_t).gather(1, actions_t)

    with torch.no_grad():
        next_q = target_net(next_states_t)
        valid_mask = next_states_t[:, 0, 0, :] == 0
        masked_next = torch.where(
            valid_mask, next_q, torch.full_like(next_q, -float("inf"))
        )
        max_next = masked_next.max(dim=1, keepdim=True)[0]
        has_valid = valid_mask.any(dim=1, keepdim=True)
        max_next = torch.where(has_valid, max_next, torch.zeros_like(max_next))
        targets = rewards_t + gamma * max_next * masks_t

    loss = F.mse_loss(q_values, targets)
    optimizer.zero_grad()
    loss.backward()
    optimizer.step()
    return float(loss.item())


def train_dqn(
    episodes: int = 2000,
    enemy: str = "random",
    buffer_limit: int = 50_000,
    batch_size: int = 64,
    gamma: float = 0.99,
    log_interval: int = 50,
) -> QNetwork:
    if not HAS_TORCH:
        raise ImportError("PyTorch가 설치되어야 학습(train_dqn)을 실행할 수 있습니다.")
    env = ConnectFourTrainer(enemy=enemy)
    buffer = ReplayBuffer(capacity=buffer_limit)

    q_net = QNetwork(env.cols).to(DEVICE)
    target_net = QNetwork(env.cols).to(DEVICE)
    target_net.load_state_dict(q_net.state_dict())
    optimizer = torch.optim.Adam(q_net.parameters(), lr=5e-4)

    running_reward = 0.0
    last_loss = 0.0
    required_replay = max(batch_size, WARMUP_STEPS)

    for episode in range(episodes):
        state = env.reset()
        done = False
        epsilon = epsilon_by_episode(episode)
        episode_reward = 0.0

        while not done:
            playable = playable_columns_from_state(state)
            state_tensor = state_to_tensor(state).to(DEVICE)
            action = q_net.act(state_tensor, playable, epsilon)

            next_state, reward, done = env.step(action)
            buffer.push(state, action, reward, next_state, 0.0 if done else 1.0)

            state = next_state
            episode_reward += reward

            if len(buffer) >= required_replay:
                for _ in range(UPDATES_PER_STEP):
                    batch = buffer.sample(batch_size)
                    last_loss = optimize_td(q_net, target_net, batch, optimizer, gamma)

        running_reward += episode_reward

        if (episode + 1) % TARGET_SYNC_INTERVAL == 0:
            target_net.load_state_dict(q_net.state_dict())

        if (episode + 1) % log_interval == 0:
            avg_reward = running_reward / log_interval
            print(
                f"[DQN] ep={episode + 1:04d} avg_reward={avg_reward:.3f} "
                f"eps={epsilon:.3f} buffer={len(buffer)} loss={last_loss:.4f}"
            )
            running_reward = 0.0

    q_net.eval()
    return q_net


# 5) Embedded weight helpers ---------------------------------------------------


def _literal_to_numpy_arrays(literal: Dict[str, List]) -> Dict[str, np.ndarray]:
    state_dict: Dict[str, np.ndarray] = {}
    for name, values in literal.items():
        state_dict[name] = np.asarray(values, dtype=np.float32)
    return state_dict


def load_embedded_state_dict() -> Optional[Dict[str, np.ndarray]]:
    if EMBEDDED_STATE_DICT is None:
        return None
    return _literal_to_numpy_arrays(EMBEDDED_STATE_DICT)


def export_state_dict_literal(model: QNetwork) -> str:
    if not HAS_TORCH:
        raise ImportError("PyTorch 없이 state_dict를 내보낼 수 없습니다.")
    lines = ["EMBEDDED_STATE_DICT = {"]
    for name, tensor in model.state_dict().items():
        values = tensor.detach().cpu().tolist()
        lines.append(f"    {name!r}: {values},")
    lines.append("}")
    return "\n".join(lines)


class EmbeddedPolicy:
    """Pure NumPy inference network built from exported weights."""

    REQUIRED_KEYS = [
        "cnn.0.weight",
        "cnn.0.bias",
        "cnn.2.weight",
        "cnn.2.bias",
        "fc.weight",
        "fc.bias",
    ]

    def __init__(self, weights: Dict[str, np.ndarray]):
        missing = [key for key in self.REQUIRED_KEYS if key not in weights]
        if missing:
            raise ValueError(f"Missing weights for keys: {missing}")

        self.w1 = np.asarray(weights["cnn.0.weight"], dtype=np.float32)
        self.b1 = np.asarray(weights["cnn.0.bias"], dtype=np.float32)
        self.w2 = np.asarray(weights["cnn.2.weight"], dtype=np.float32)
        self.b2 = np.asarray(weights["cnn.2.bias"], dtype=np.float32)
        self.w_fc = np.asarray(weights["fc.weight"], dtype=np.float32)
        self.b_fc = np.asarray(weights["fc.bias"], dtype=np.float32)

        self.action_dim = self.b_fc.shape[0]

    @staticmethod
    def _conv2d(inputs: np.ndarray, weight: np.ndarray, bias: np.ndarray) -> np.ndarray:
        """Naive conv2d for tiny feature maps (channels, height, width)."""
        out_channels, in_channels, k_h, k_w = weight.shape
        _, in_h, in_w = inputs.shape
        out_h = in_h - k_h + 1
        out_w = in_w - k_w + 1
        out = np.zeros((out_channels, out_h, out_w), dtype=np.float32)

        for oc in range(out_channels):
            for ic in range(in_channels):
                kernel = weight[oc, ic]
                for i in range(out_h):
                    h_slice = slice(i, i + k_h)
                    for j in range(out_w):
                        w_slice = slice(j, j + k_w)
                        region = inputs[ic, h_slice, w_slice]
                        out[oc, i, j] += float(np.sum(region * kernel))
            out[oc] += bias[oc]
        return out

    def forward(self, state: np.ndarray) -> np.ndarray:
        x = state.astype(np.float32)
        x = self._conv2d(x, self.w1, self.b1)
        x = np.maximum(x, 0.0, out=x)
        x = self._conv2d(x, self.w2, self.b2)
        x = np.maximum(x, 0.0, out=x)
        flat = x.reshape(-1)
        logits = self.w_fc @ flat + self.b_fc
        return logits

    def act(self, state: np.ndarray, playable: List[int]) -> int:
        logits = self.forward(state)
        masked = np.full(self.action_dim, -np.inf, dtype=np.float32)
        masked[playable] = logits[playable]
        return int(np.argmax(masked))


# 6) Kaggle submission agent ---------------------------------------------------


_INFERENCE_POLICY: Optional[EmbeddedPolicy] = None
_INFERENCE_READY: bool = False


def load_inference_model(action_dim: int) -> Tuple[Optional[EmbeddedPolicy], bool]:
    global _INFERENCE_POLICY, _INFERENCE_READY

    if _INFERENCE_POLICY is not None:
        return _INFERENCE_POLICY, _INFERENCE_READY

    literal_state = load_embedded_state_dict()
    ready = False
    policy: Optional[EmbeddedPolicy] = None

    if literal_state is not None:
        try:
            candidate = EmbeddedPolicy(literal_state)
            if candidate.action_dim == action_dim:
                policy = candidate
                ready = True
        except ValueError:
            policy = None

    _INFERENCE_POLICY = policy
    _INFERENCE_READY = ready
    return policy, ready


def my_agent(observation, configuration):
    """Kaggle entry point."""
    try:
        board = _extract_board(observation)
        playable = find_playable_columns(board, configuration)

        if not playable:
            return 0

        action_dim = _get_cfg_value(configuration, "columns", 7)
        policy, ready = load_inference_model(action_dim)
        if not ready or policy is None:
            return fallback_move(playable, configuration)

        state = state_from_board(board, configuration)
        return policy.act(state, playable)

    except Exception:
        board = _extract_board(observation)
        columns = _get_cfg_value(configuration, "columns", 7)
        fallback_playable: List[int] = []
        for c in range(columns):
            if c < len(board) and board[c] == 0:
                fallback_playable.append(c)
        if not fallback_playable:
            return 0
        center = columns // 2
        return center if center in fallback_playable else fallback_playable[0]


if __name__ == "__main__":
    if not HAS_TORCH:
        raise ImportError("PyTorch가 설치된 환경에서만 학습 스크립트를 실행할 수 있습니다.")

    trained_policy = train_dqn(episodes=2000)
    trained_policy_cpu = trained_policy.to("cpu")
    literal = export_state_dict_literal(trained_policy_cpu)

    if EMBEDDED_STATE_OUTPUT is not None:
        try:
            EMBEDDED_STATE_OUTPUT.write_text(literal, encoding="utf-8")
            print(f"[INFO] Embedded weights written to {EMBEDDED_STATE_OUTPUT}")
        except OSError as exc:
            print(f"[WARN] Could not write literal to {EMBEDDED_STATE_OUTPUT}: {exc}")

    print("--- Copy the literal below into EMBEDDED_STATE_DICT in DQN.py ---")
    print(literal)


# ================= Kaggle용 진입점 함수 =================
def agent(observation, configuration):
    """Kaggle이 호출하는 기본 에이전트 함수."""
    return my_agent(observation, configuration)
